/// <summary>
/// Unit test class for SOrderTable using SysTest framework.
/// </summary>
internal final class SOrderTableTest_Unit extends SysTestCase
{
}

Method.Source:
/// <summary>
/// Tests that initValue() sets Status to Draft.
/// </summary>
[SysTestMethodAttribute]
public void testInitValueStatus()
{
    SOrderTable orderTable;

    orderTable.initValue();
    this.assertEquals(SOrderStatus::Draft, orderTable.Status);
}

/// <summary>
/// Tests that initValue() sets TotalAmount to 0.
/// </summary>
[SysTestMethodAttribute]
public void testInitValueTotalAmount()
{
    SOrderTable orderTable;

    orderTable.initValue();
    this.assertEquals(0, orderTable.TotalAmount);
}

/// <summary>
/// Tests that OrderDate is set after initValue().
/// </summary>
[SysTestMethodAttribute]
public void testInitValueOrderDate()
{
    SOrderTable orderTable;

    orderTable.initValue();
    this.assertTrue(orderTable.OrderDate != dateNull());
}
